170	  /// "Ready for Review" button moved into the panel body (above the title) so it can't crowd the
171	  /// section title in a narrow inspector (issue #93 feedback). Order is left → right, so the ellipsis
172	  /// stays rightmost (matching the other section headers).
173	  @ViewBuilder private var prHeaderAccessory: some View {
174	    HStack(spacing: 6) {
175	      prNumberLink
176	      prActionsMenu
177	    }
178	  }
