180	  /// The PR number badge, now a link that opens the PR in the browser (issue #77) — it replaces the
181	  /// in-panel status row's open-in-browser affordance, so the header always carries the link. Tinted
182	  /// by PR state (open/draft/merged/closed), but red when the PR's checks are failing.
183	  @ViewBuilder private var prNumberLink: some View {
184	    if store.githubCLIStatus == .available, let status = selectedStatus, let pr = status.pr {
185	      let badge = PRPresentation.badge(pr)
186	      // Failing checks only recolor an *open* PR — a merged (purple) / closed (red) badge shouldn't
187	      // be repainted by stale check history.
188	      let failing = pr.state == .open && PRPresentation.isFailing(status)
189	      let tint: Color = failing ? .red : badge.semantic.color
190	      let failSuffix = failing ? ", checks failing" : ""
191	      PRNumberBadge(
192	        number: pr.number, tint: tint, url: URL(string: pr.url),
193	        help: "Pull request #\(String(pr.number)): \(badge.label)\(failSuffix). Open in browser.",
194	        accessibility:
195	          "Pull request #\(String(pr.number)), \(badge.label)\(failSuffix), open in browser")
196	    }
197	  }
