199	  /// The PR header menu: "Go to Pull Request" (always available when there's a PR), plus the
200	  /// state-dependent write actions (ready/draft, close, reopen — Phase 2b; destructive ones route
201	  /// through a confirmation dialog). Shown whenever there's a PR, so a merged/closed PR with no
202	  /// remaining actions can still be opened in the browser.
203	  @ViewBuilder private var prActionsMenu: some View {
204	    if store.githubCLIStatus == .available, let pr = selectedStatus?.pr,
205	      let sid = store.selectedTargetID
206	    {
207	      let actions = PRAction.available(for: pr)
208	      Menu {
209	        Button {
210	          if let url = URL(string: pr.url) { openURL(url) }
211	        } label: {
212	          Label("Go to Pull Request", systemImage: "arrow.up.right.square")
213	        }
214	        if !actions.isEmpty {
215	          Divider()
216	          ForEach(actions, id: \.self) { action in
217	            Button(role: action.isDestructive ? .destructive : nil) {
218	              if action.needsConfirmation {
219	                pendingConfirm = PendingPRAction(action: action, number: pr.number, sid: sid)
220	              } else {
221	                store.performPRAction(action, number: pr.number, on: sid)
222	              }
223	            } label: {
224	              Label(action.label, systemImage: action.systemImage)
225	            }
226	          }
227	        }
228	      } label: {
229	        Image(systemName: "ellipsis").font(.system(size: 11)).foregroundStyle(.secondary)
230	      }
231	      // `.menuStyle(.button)` (NOT `.borderlessButton`) renders the trigger as a SwiftUI button, so
232	      // `InspectorMenuButtonStyle` can give it the same rounded hover fill + comfortable click
233	      // target as the other header buttons. A `.borderlessButton` menu is AppKit-backed and never
234	      // reports hover. Clicking still drops the native menu — consistent with the rest of the app.
235	      .menuStyle(.button)
236	      .buttonStyle(InspectorMenuButtonStyle())
237	      .menuIndicator(.hidden)
238	      .fixedSize()
239	      .disabled(store.prActionInFlight)
240	      .help("Pull request actions")
241	      .accessibilityLabel("Pull request actions")
242	    }
