250	  /// The selected workroom's status, or nil when a non-target (project) or nothing is selected —
251	  /// drives the header indicators so a collapsed section still shows state.
252	  private var selectedStatus: WorkroomStatus? {
253	    guard let sid = store.inspectorTargetID else { return nil }
254	    if case .project = sid { return nil }
255	    return store.workroomStatuses[sid]
