258	  /// Changes header indicator: how many files changed (a capsule count) and the working-tree line counts
259	  /// (`+N` green / `-M` red) when there's a delta. Nothing at all if clean.
260	  ///
261	  /// The file count is deliberately NOT inside the line-counts branch. `lineCountsHelp` is nil for an
262	  /// untracked-only dirty tree, which is exactly a case where files changed and no `+/−` can be
263	  /// computed — the count is the only thing there is to say, so it has to render on its own.
264	  ///
265	  /// **The dirty dot is gone; the unknown one is not.** `VCSStatusPresentation.dot` answers three
266	  /// different questions, and the count only replaces one of them. Its `.dirty` circle said "this tree
267	  /// has changes", which is now the capsule beside it saying so with a number; its conflict triangle is
268	  /// already rendered here in its own right. But its `questionmark.circle` says the probe FAILED —
269	  /// timed out, busy, not a repository — and a failed probe reports no files and no line counts, so
270	  /// dropping it wholesale would render "status unavailable" identically to "clean". That case keeps its
271	  /// glyph, and with it the specific reason in the tooltip.
272	  private var changesIndicator: AnyView {
273	    guard let s = selectedStatus else { return AnyView(EmptyView()) }
274	    let ins = s.insertions ?? 0
275	    let del = s.deletions ?? 0
276	    // `changedFiles` mirrors `jjWorkingCopy?.files` for jj (both come from the one summary probe), so
277	    // this is the same number for both backends and matches the rows rendered below.
278	    let files = s.changedFiles?.count ?? 0
279	    let countsHelp = VCSStatusPresentation.lineCountsHelp(s)
280	    // `!s.conflicted` because `dot` checks conflict FIRST and would hand back the triangle this row
281	    // already draws — a status that is both conflicted and unreadable would otherwise show two.
282	    let dot = s.isUnknown && !s.conflicted ? VCSStatusPresentation.dot(s) : nil
283	    if files == 0, countsHelp == nil, dot == nil { return AnyView(EmptyView()) }
284	    return AnyView(
285	      HStack(spacing: 5) {
286	        if s.conflicted {
287	          Image(systemName: "exclamationmark.triangle.fill")
288	            .font(.system(size: 9)).foregroundStyle(Color.red)
289	        }
290	        if files > 0 { ChangedFileCountBadge(count: files) }
291	        if let countsHelp {
292	          HStack(spacing: 5) {
293	            if ins > 0 { Text("+\(ins)").foregroundStyle(.green) }
294	            if del > 0 { Text("-\(del)").foregroundStyle(.red) }
295	          }
296	          .help(countsHelp)
297	        }
298	        if let dot {
299	          Image(systemName: dot.symbol).font(.system(size: 9)).foregroundStyle(dot.semantic.color)
300	            .help(dot.accessibility)
301	        }
302	      }
303	      .font(.caption).monospacedDigit())
304	  }
305	
306	  // VoiceOver text for each header indicator (the visual badge can't be read through the collapse
307	  // button's own label), appended to the section's accessibility label.
308	
309	  private var changesIndicatorLabel: String {
310	    guard let s = selectedStatus else { return "" }
311	    // The capsule count is a `Text` inside the combined header element, so it never reaches the
312	    // accessibility tree on its own — it has to be spoken here or not at all.
313	    // `> 0` so this tracks the badge exactly — a clean tree renders no capsule and must speak none.
314	    let files = (s.changedFiles?.count).flatMap {
315	      $0 > 0 ? ChangedFileCountBadge.phrase(count: $0) : nil
316	    }
317	    // Mirrors what the row now draws: line counts, or the unavailable reason, and no longer "working
318	    // tree has changes" — the count phrase above already says that, in files rather than in prose.
319	    let detail =
320	      VCSStatusPresentation.lineCountsHelp(s)
321	      ?? (s.isUnknown ? VCSStatusPresentation.dot(s)?.accessibility : nil)
322	    return [files, detail].compactMap { $0 }.joined(separator: ", ")
323	  }
324	}
