392	/// One changed-file row: a colored change-kind letter (M/A/D/…), the filename, then its parent
393	/// directory dimmed (issue #24 feedback). Clicking opens the file's diff in the workroom's tab strip
394	/// (issue #66): a single click opens it in preview mode (eagerly — the diff appears at once), a quick
395	/// double-click persists it. `source` is the row's group (git worktree / jj `@` / jj `@-`), so the
396	/// diff resolves against the right revision. The directory yields first when space is tight
397	/// (truncates from the head). The change kind is spelled out in the accessibility label.
398	private struct ChangedFileRow: View {
399	  let file: ChangedFile
400	  /// Which revision this row's diff comes from — the Changes group it's rendered under.
401	  let source: DiffSource
402	  @EnvironmentObject var store: AppStore
403	  /// Observed so the row's selected state tracks which diff tab is focused (the tab strip lives in
404	  /// a separate observation tree from the inspector).
405	  @ObservedObject var sessions: TerminalSessions
406	  @State private var hovering = false
407	  /// Time of the last click, so a quick second click promotes the preview tab to persisted (eager
408	  /// single/double discrimination — the single click never waits).
409	  @State private var lastClick: Date?
410	  /// Observed so the hover toolbar / context-menu "Open file in <editor>" label updates live when
411	  /// the user changes Settings → "Open file paths in" (issue #93); otherwise it'd be stale until an
412	  /// unrelated redraw.
413	  @Default(.filePathEditor) private var filePathEditorID
414	  private let theme = ThemeService.shared
415	
416	  var body: some View {
417	    let (dir, name) = ChangesPanel.splitPath(file.path)
418	    // Baseline-aligned, not centered: the path is a smaller face than the filename, so centering
419	    // would float it off the name's baseline.
420	    HStack(alignment: .firstTextBaseline, spacing: 6) {
421	      Text(letter)
422	        .font(.system(.callout, design: .monospaced))
423	        .foregroundStyle(color)
424	        .frame(width: 14, alignment: .leading)
425	      Text(name)
426	        .font(.callout)
427	        .foregroundStyle(isSelected ? theme.tokens.accent : .primary)
428	        .lineLimit(1).truncationMode(.middle)
429	        .layoutPriority(1)
430	      if !dir.isEmpty {
431	        // Same face as the History detail file list's path line (`ChangesetDetailView.fileRow`):
432	        // caption, monospaced, `.tertiary`. Matching the tint matters — the two panels sit one tab
433	        // apart, and `.secondary` beside `.tertiary` reads as two different kinds of text rather
434	        // than the same one.
435	        //
436	        // Truncation is the one thing that deliberately differs. History stacks the full path UNDER
437	        // the name and truncates it in the middle; here the directory sits INLINE before a
438	        // `layoutPriority(1)` name, where the tail (the directory the file is actually in) is the
439	        // part that identifies it — so it truncates from the head. Middle-truncation on a one-line
440	        // inline dir would clip both ends and leave the least useful segment.
441	        Text(dir)
442	          .font(.system(.caption, design: .monospaced))
443	          .foregroundStyle(.tertiary)
444	          .lineLimit(1).truncationMode(.head)
445	      }
446	      Spacer(minLength: 0)
447	    }
448	    .padding(.vertical, 4)
449	    .padding(.horizontal, 6)
450	    .frame(maxWidth: .infinity, alignment: .leading)
451	    .background(
452	      // Square, full-width band (no corner radius): bleed past the section's 12pt inset so the
453	      // hover/selection highlight fills the inspector width edge-to-edge (issue #93 feedback).
454	      Rectangle()
455	        .fill(isSelected ? theme.tokens.rowSelection : (hovering ? theme.tokens.rowHover : .clear))
456	        .padding(.horizontal, -12)
457	    )
458	    // The row's tooltip describes its click action (open the diff). Applied BEFORE the hover overlay
459	    // so it scopes to the row content only — the trailing "Open file" button, painted on top, keeps
460	    // its OWN tooltip. A `.help` applied after the overlay covers the whole row and occludes the
461	    // button's, so hovering the button wrongly showed "Open diff for …" (issue #117 follow-up).
462	    // A moved file's old path has nowhere to go in this single-line row, so the tooltip carries it
463	    // (`old → new`); the wider changeset detail list shows it inline.
464	    .help(file.oldPath == nil ? "Open diff" : "Open diff — \(renamePath)")
465	    // Hover toolbar (issue #93): a content-sized cluster pinned to the trailing edge, painted over
466	    // the path. Only the button area intercepts clicks (it opens the file) — the rest of the row
467	    // still opens the diff. Built only while hovering, so the editor-name lookup runs on hover only.
468	    .overlay(alignment: .trailing) { if hovering { rowToolbar } }
469	    .contentShape(Rectangle())
470	    .onHover { hovering = $0 }
471	    .onTapGesture {
472	      if NSEvent.modifierFlags.contains(.command) {
473	        store.openChangedFileInEditor(file)  // ⌘-click → open the file, not the diff (issue #93)
474	        lastClick = nil  // clear any pending double-click state so the next plain click is fresh
475	        return
476	      }
477	      let now = Date()
478	      if let last = lastClick, now.timeIntervalSince(last) < 0.35 {
479	        store.openDiffPersistent(file, source: source)  // quick second click → persist
480	        lastClick = nil
481	      } else {
482	        store.openDiffPreview(file, source: source)  // eager: open the preview immediately
483	        lastClick = now
484	      }
485	    }
486	    .accessibilityElement(children: .ignore)
487	    .accessibilityAddTraits(isSelected ? [.isButton, .isSelected] : .isButton)
488	    .accessibilityIdentifier("changes.file.\(file.path)")
489	    .accessibilityLabel(
490	      accessibilityLabel(name: name, dir: dir)
491	    )
492	    // A non-pointer path to the open-file actions (the hover toolbar is mouse-only): keyboard /
493	    // VoiceOver reach them here. "Open File" opens the in-app viewer (issue #117); "Open File in …"
494	    // keeps the external-editor path (issue #93). Both no-op for a deleted file (no working copy).
495	    .contextMenu {
496	      Button {
497	        store.openChangedFileInApp(file)
498	      } label: {
499	        Label("Open File", systemImage: "doc.text")
500	      }
501	      .disabled(file.change == .deleted)
502	      Button {
503	        store.openChangedFileInEditor(file)
504	      } label: {
505	        Label("Open File in \(openFileEditorName)", systemImage: "arrow.up.forward.app")
506	      }
507	      .disabled(file.change == .deleted)
508	    }
509	  }
510	
511	  /// The trailing hover toolbar: the in-app "Open File" button (extensible to more buttons; issue
512	  /// #117). Hidden for a deleted file — there's no working copy to open — so the toolbar renders
513	  /// nothing. Its backing is the same opaque `rowHover`/`rowSelection` token the row uses for its
514	  /// highlight, so the toolbar is solid (occludes the path text) and exactly the same colour as the row.
515	  @ViewBuilder private var rowToolbar: some View {
516	    if file.change != .deleted {
517	      HStack(spacing: 2) {
518	        TabToolbarButton(
519	          systemImage: "doc.text", help: "Open file",
520	          accessibilityLabel: "Open file",
521	          identifier: "changes.file.openFile.\(file.path)"
522	        ) {
523	          store.openChangedFileInApp(file)
524	        }
525	      }
526	      .padding(.horizontal, 2)
527	      .background(
528	        // The same opaque token the row fills its highlight with — solid (occludes the path text) and
529	        // identical in colour to the row by construction.
530	        RoundedRectangle(cornerRadius: 5)
531	          .fill(isSelected ? theme.tokens.rowSelection : theme.tokens.rowHover)
532	      )
533	      .fixedSize()
534	    }
535	  }
