537	  /// Display name of the editor the "Open file in…" action targets — the Settings "Open file paths
538	  /// in" choice (`ExternalEditor.forFilePaths`), or "your default app" when unset. Recomputes when
539	  /// `filePathEditorID` changes (issue #93).
540	  private var openFileEditorName: String {
541	    ExternalEditor.forFilePaths?.name ?? "your default app"
542	  }
543	
544	  /// True when the selected target's focused content tab is this row — either its diff (opened by a
545	  /// row click) or its file (opened by the in-app "Open File", issue #117) — so the row that's
546	  /// showing in the pane reads as selected. The file match ignores `source` since a file tab has no
547	  /// revision; the diff match keeps it so the same path under `@` vs `@-` selects the right row.
548	  private var isSelected: Bool {
549	    guard let target = store.selectedTarget, let tab = sessions.focusedTab(for: target)
550	    else { return false }
551	    switch tab.content {
552	    case .diff(let descriptor): return descriptor.path == file.path && descriptor.source == source
553	    case .file(let descriptor): return descriptor.path == file.path
554	    default: return false
555	    }
556	  }
