558	  // Letter / colour / word live in `ChangeBadge` (Core) so the mapping is unit-testable — see its
559	  // doc for why `.conflicted` is `"!"` in its own colour rather than `"C"` in deletion's red.
560	  private var letter: String { ChangeBadge.letter(file.change) }
561	  private var color: Color { ChangeBadge.color(file.change, theme.tokens) }
562	  private var changeWord: String { ChangeBadge.word(file.change) }
563	  /// `old → new`, for the tooltip and accessibility label of a moved file.
564	  private var renamePath: String {
565	    ChangeBadge.pathLine(path: file.path, oldPath: file.oldPath)
566	  }
567	
568	  /// The row's spoken label. A moved file says where it came from — VoiceOver has no tooltip to fall
569	  /// back on, and the row only shows the new path.
570	  private func accessibilityLabel(name: String, dir: String) -> String {
571	    let place = dir.isEmpty ? "" : ", in \(dir)"
572	    let from = file.oldPath.map { ", from \($0)" } ?? ""
573	    return "\(name), \(changeWord)\(place)\(from), open diff"
574	  }
575	}
