    let app = launchedApp(syncState: "clean")
    XCTAssertTrue(waitExists(fetch(app)))
    XCTAssertTrue(fetch(app).isEnabled)
    XCTAssertTrue(button(app, id: "vcs.toolbar.fetch").isHittable)
    button(app, id: "vcs.toolbar.fetch").click()
    XCTAssertTrue(
